"""Packs: custom sets of exercises in a single TOML file, generated by an AI from course
material, installed with `drill pack add` and practised on their own."""

from __future__ import annotations

import re
import shutil
import tomllib
from dataclasses import dataclass
from pathlib import Path

from .exercises import MODES, Exercise, ExerciseError, parse
from .store import data_dir

SLUG = re.compile(r"[^a-z0-9]+")


def packs_dir() -> Path:
    return data_dir() / "packs"


def slugify(text: str) -> str:
    return SLUG.sub("-", text.lower()).strip("-") or "pack"


@dataclass
class Pack:
    slug: str
    name: str
    description: str
    path: Path
    exercises: list[Exercise]
    errors: list[str]  # exercises that could not be read

    def counts(self) -> str:
        per_mode = [(mode, sum(ex.mode == mode for ex in self.exercises)) for mode in MODES]
        return " · ".join(f"{mode} {n}" for mode, n in per_mode if n)

    def langs(self) -> list[str]:
        from .langs import LANGUAGES

        return [key for key in LANGUAGES if any(ex.supports(key) for ex in self.exercises)]


def load(path: Path, slug: str | None = None) -> Pack:
    """Read a pack file. Exercises that fail to parse are reported in Pack.errors."""
    slug = slug or path.stem
    try:
        data = tomllib.loads(path.read_text())
    except tomllib.TOMLDecodeError as e:
        raise ExerciseError(f"{path.name} is not valid TOML: {e}") from None
    meta = data.get("pack", {})
    exercises, errors, seen = [], [], set()
    for index, entry in enumerate(data.get("exercises", []), 1):
        local = entry.get("id", f"exercise-{index}")
        if local in seen:
            errors.append(f"{local}: duplicate id")
            continue
        seen.add(local)
        try:
            exercises.append(parse(entry, f"{slug}:{local}", None, pack=slug))
        except (KeyError, ExerciseError) as e:
            detail = f"missing key {e}" if isinstance(e, KeyError) else str(e)
            errors.append(f"{local}: {detail}")
    if not exercises and not errors:
        errors.append("no [[exercises]] found")
    return Pack(
        slug, meta.get("name", slug), meta.get("description", ""), path, exercises, errors
    )


def installed() -> list[Pack]:
    folder = packs_dir()
    packs = []
    for path in sorted(folder.glob("*.toml")) if folder.is_dir() else []:
        try:
            packs.append(load(path))
        except ExerciseError as e:
            packs.append(Pack(path.stem, path.stem, f"unreadable: {e}", path, [], [str(e)]))
    return packs


def find(name: str) -> Pack | None:
    """An installed pack by slug, or by its name or a part of it."""
    packs = installed()
    for pack in packs:
        if name in (pack.slug, pack.name):
            return pack
    matches = [p for p in packs if name.lower() in p.slug or name.lower() in p.name.lower()]
    return matches[0] if len(matches) == 1 else None


def install(source: Path, slug: str) -> Path:
    target = packs_dir() / f"{slug}.toml"
    target.parent.mkdir(parents=True, exist_ok=True)
    shutil.copyfile(source, target)
    return target
